BEGIN TRANSACTION;
CREATE TABLE feature_complexity(repo_root VARCHAR, change_id VARCHAR, complexity VARCHAR, schema_name VARCHAR, started_at TIMESTAMP, completed_at TIMESTAMP, upserted_at TIMESTAMP DEFAULT(CURRENT_TIMESTAMP), PRIMARY KEY(repo_root, change_id));;
CREATE TABLE feature_metrics(repo_root VARCHAR, change_id VARCHAR, schema_name VARCHAR, tasks_total INTEGER, tasks_planned INTEGER, tasks_added INTEGER, tasks_completed INTEGER, tasks_failed INTEGER, resolve_rate DOUBLE, pass_at_1 DOUBLE, pass_at_2 DOUBLE, regressions INTEGER, regression_rate DOUBLE, retries_total INTEGER, human_interventions INTEGER, files_changed INTEGER, insertions INTEGER, deletions INTEGER, total_commits INTEGER, rework_commits INTEGER, rework_rate DOUBLE, review_scores_json VARCHAR, review_score_avg DOUBLE, wall_clock_minutes DOUBLE, "source" VARCHAR, computed_at TIMESTAMP DEFAULT(CURRENT_TIMESTAMP), PRIMARY KEY(repo_root, change_id));;
CREATE TABLE pricing(model_id VARCHAR, input_usd DOUBLE NOT NULL, output_usd DOUBLE NOT NULL, cache_read_usd DOUBLE NOT NULL, cache_creation_usd DOUBLE, is_local BOOLEAN DEFAULT(CAST('f' AS BOOLEAN)) NOT NULL, effective_from TIMESTAMP, PRIMARY KEY(model_id, effective_from));;
CREATE TABLE schema_migrations("name" VARCHAR PRIMARY KEY, applied_at TIMESTAMP DEFAULT(CURRENT_TIMESTAMP));;
CREATE TABLE step_events(repo_root VARCHAR, change_id VARCHAR, phase VARCHAR, step_id VARCHAR, attempt INTEGER, agent_name VARCHAR NOT NULL, agent_id VARCHAR, status VARCHAR, schema_name VARCHAR, started_at TIMESTAMP, ended_at TIMESTAMP, duration_ms BIGINT, model VARCHAR, input_tokens BIGINT, output_tokens BIGINT, cache_read_input_tokens BIGINT, cache_creation_input_tokens BIGINT, cost_usd DOUBLE, turns BIGINT, tool_calls_json VARCHAR, artifacts_json VARCHAR, escalation_json VARCHAR, upserted_at TIMESTAMP DEFAULT(CURRENT_TIMESTAMP), PRIMARY KEY(repo_root, change_id, phase, step_id, attempt, status));;
CREATE TABLE tool_calls(repo_root VARCHAR, change_id VARCHAR, phase VARCHAR, step_id VARCHAR, attempt INTEGER, agent_name VARCHAR NOT NULL, tool_name VARCHAR NOT NULL, is_mcp BOOLEAN NOT NULL, call_seq INTEGER, called_at VARCHAR, duration_ms BIGINT, PRIMARY KEY(repo_root, change_id, phase, step_id, attempt, call_seq));;
CREATE VIEW agent_report AS SELECT repo_root, change_id, agent_name, COALESCE(sum(cost_usd), 0.0) AS cost_usd, COALESCE(sum(input_tokens), 0) AS input_tokens, COALESCE(sum(output_tokens), 0) AS output_tokens, COALESCE(sum(duration_ms), 0) AS duration_ms, count_star() AS step_count FROM step_events GROUP BY repo_root, change_id, agent_name ORDER BY repo_root, change_id, agent_name ASC;;
CREATE VIEW feature_report AS WITH base AS (SELECT se.repo_root, se.change_id, COALESCE(sum(se.cost_usd), 0.0) AS cost_usd, COALESCE(sum(se.input_tokens), 0) AS input_tokens, COALESCE(sum(se.output_tokens), 0) AS output_tokens, COALESCE(sum(se.cache_creation_input_tokens), 0) AS cache_creation_input_tokens, COALESCE(sum(se.cache_read_input_tokens), 0) AS cache_read_input_tokens, ((COALESCE(sum(se.input_tokens), 0) + COALESCE(sum(se.output_tokens), 0)) + COALESCE(sum(se.cache_creation_input_tokens), 0)) AS total_tokens, COALESCE(sum(se.turns), 0) AS turns, COALESCE(sum(se.duration_ms), 0) AS duration_ms, count_star() AS step_count, COALESCE(sum(CASE  WHEN ((se.attempt > 1)) THEN (se.cost_usd) ELSE 0.0 END), 0.0) AS rework_cost, COALESCE(sum(se.cost_usd), 0.0) AS rework_denom FROM step_events AS se GROUP BY se.repo_root, se.change_id), dom_model AS (SELECT repo_root, change_id, model FROM (SELECT repo_root, change_id, model, sum(input_tokens) AS input_sum, row_number() OVER (PARTITION BY repo_root, change_id ORDER BY sum(input_tokens) DESC NULLS LAST) AS rn FROM step_events WHERE (model IS NOT NULL) GROUP BY repo_root, change_id, model) AS ranked WHERE (rn = 1)), priced AS (SELECT model_id, input_usd, output_usd, cache_read_usd, cache_creation_usd, row_number() OVER (PARTITION BY model_id ORDER BY effective_from DESC) AS rn FROM pricing), tool_count AS (SELECT repo_root, change_id, count_star() AS tool_calls_count FROM tool_calls GROUP BY repo_root, change_id), per_agent_tokens_agg AS (SELECT repo_root, change_id, CAST(json_group_object(agent_name, agent_stats) AS VARCHAR) AS per_agent_tokens FROM (SELECT repo_root, change_id, agent_name, json_object('total_tokens', (COALESCE(sum(input_tokens), 0) + COALESCE(sum(output_tokens), 0)), 'input_tokens', COALESCE(sum(input_tokens), 0), 'output_tokens', COALESCE(sum(output_tokens), 0), 'cost_usd', COALESCE(sum(cost_usd), 0.0), 'duration_ms', COALESCE(sum(duration_ms), 0), 'step_count', count_star()) AS agent_stats FROM step_events GROUP BY repo_root, change_id, agent_name) AS t GROUP BY repo_root, change_id), per_agent_tools_agg AS (SELECT tc.repo_root, tc.change_id, CAST(json_group_object(agent_name, tool_map) AS VARCHAR) AS per_agent_tools FROM (SELECT repo_root, change_id, agent_name, json_group_object(tool_name, calls) AS tool_map FROM (SELECT repo_root, change_id, agent_name, tool_name, count_star() AS calls FROM tool_calls GROUP BY repo_root, change_id, agent_name, tool_name) GROUP BY repo_root, change_id, agent_name) AS tc GROUP BY tc.repo_root, tc.change_id), per_tool_uses_agg AS (SELECT repo_root, change_id, CAST(json_group_object(tool_name, calls) AS VARCHAR) AS per_tool_uses FROM (SELECT repo_root, change_id, tool_name, count_star() AS calls FROM tool_calls GROUP BY repo_root, change_id, tool_name) GROUP BY repo_root, change_id), per_step_agg AS (SELECT step_data.repo_root, step_data.change_id, CAST(json_group_object(step_id, json_object('total_tokens', total_tokens, 'tool_uses', tool_uses, 'duration_ms', duration_ms, 'executions', executions)) AS VARCHAR) AS per_step FROM (SELECT se.repo_root, se.change_id, se.step_id, (COALESCE(sum(se.input_tokens), 0) + COALESCE(sum(se.output_tokens), 0)) AS total_tokens, COALESCE(sum(se.duration_ms), 0) AS duration_ms, count_star() AS executions, COALESCE((SELECT count_star() FROM tool_calls AS tc WHERE ((tc.repo_root = se.repo_root) AND (tc.change_id = se.change_id) AND (tc.step_id = se.step_id))), 0) AS tool_uses FROM step_events AS se GROUP BY se.repo_root, se.change_id, se.step_id) AS step_data GROUP BY step_data.repo_root, step_data.change_id)SELECT b.repo_root, b.change_id, b.cost_usd, b.input_tokens, b.output_tokens, b.cache_creation_input_tokens, b.cache_read_input_tokens, b.total_tokens, b.turns, b.duration_ms, b.step_count, CASE  WHEN ((b.rework_denom = 0)) THEN (0.0) ELSE (b.rework_cost / b.rework_denom) END AS rework_ratio, dm.model AS model, COALESCE(p.input_usd, pd.input_usd, 15.0) AS pricing_input_usd, COALESCE(p.output_usd, pd.output_usd, 75.0) AS pricing_output_usd, COALESCE(p.cache_read_usd, pd.cache_read_usd, 1.5) AS pricing_cache_read_usd, COALESCE(p.cache_creation_usd, pd.cache_creation_usd, 18.75) AS pricing_cache_creation_usd, (((((b.input_tokens + b.cache_creation_input_tokens) + b.cache_read_input_tokens) * COALESCE(p.input_usd, pd.input_usd, 15.0)) / 1000000.0) + ((b.output_tokens * COALESCE(p.output_usd, pd.output_usd, 75.0)) / 1000000.0)) AS gross_usd, COALESCE(tc.tool_calls_count, 0) AS tool_calls_count, COALESCE(fm.schema_name, fc.schema_name, 'feature') AS category, fc.complexity AS complexity, fm.tasks_total, fm.tasks_planned, fm.tasks_added, fm.tasks_completed, fm.tasks_failed, fm.resolve_rate, fm.pass_at_1, fm.pass_at_2, fm.regressions, fm.regression_rate, fm.retries_total, fm.human_interventions, fm.files_changed, fm.insertions, fm.deletions, fm.total_commits, fm.rework_commits, fm.rework_rate, fm.review_scores_json, fm.review_score_avg, fm.wall_clock_minutes, CASE  WHEN ((COALESCE(fm.tasks_total, 0) = 0)) THEN (0.0) ELSE (b.cost_usd / fm.tasks_total) END AS cost_per_task_usd, CASE  WHEN ((COALESCE(fm.tasks_completed, 0) = 0)) THEN (0.0) ELSE (b.cost_usd / fm.tasks_completed) END AS cost_per_resolution_usd, CASE  WHEN ((COALESCE(fm.tasks_total, 0) = 0)) THEN (0) ELSE CAST((b.total_tokens / fm.tasks_total) AS BIGINT) END AS tokens_per_task, CASE  WHEN ((COALESCE(fm.tasks_completed, 0) = 0)) THEN (0) ELSE CAST((b.total_tokens / fm.tasks_completed) AS BIGINT) END AS tokens_per_resolution, CASE  WHEN ((b.output_tokens = 0)) THEN (0.0) ELSE round((CAST((b.input_tokens + b.cache_creation_input_tokens) AS DOUBLE) / b.output_tokens), 4) END AS input_output_ratio, CASE  WHEN ((((b.input_tokens + b.cache_creation_input_tokens) + b.cache_read_input_tokens) = 0)) THEN (0.0) ELSE round((CAST(b.cache_read_input_tokens AS DOUBLE) / ((b.input_tokens + b.cache_creation_input_tokens) + b.cache_read_input_tokens)), 4) END AS cache_hit_rate, COALESCE(pat.per_agent_tokens, '{}') AS per_agent_tokens, COALESCE(pato.per_agent_tools, '{}') AS per_agent_tools, COALESCE(ptu.per_tool_uses, '{}') AS per_tool_uses, COALESCE(ps.per_step, '{}') AS per_step FROM base AS b LEFT JOIN dom_model AS dm ON (((dm.repo_root = b.repo_root) AND (dm.change_id = b.change_id))) LEFT JOIN priced AS p ON (((p.model_id = dm.model) AND (p.rn = 1))) LEFT JOIN priced AS pd ON (((pd.model_id = '__default__') AND (pd.rn = 1))) LEFT JOIN tool_count AS tc ON (((tc.repo_root = b.repo_root) AND (tc.change_id = b.change_id))) LEFT JOIN feature_metrics AS fm ON (((fm.repo_root = b.repo_root) AND (fm.change_id = b.change_id))) LEFT JOIN feature_complexity AS fc ON (((fc.repo_root = b.repo_root) AND (fc.change_id = b.change_id))) LEFT JOIN per_agent_tokens_agg AS pat ON (((pat.repo_root = b.repo_root) AND (pat.change_id = b.change_id))) LEFT JOIN per_agent_tools_agg AS pato ON (((pato.repo_root = b.repo_root) AND (pato.change_id = b.change_id))) LEFT JOIN per_tool_uses_agg AS ptu ON (((ptu.repo_root = b.repo_root) AND (ptu.change_id = b.change_id))) LEFT JOIN per_step_agg AS ps ON (((ps.repo_root = b.repo_root) AND (ps.change_id = b.change_id)));;
CREATE VIEW phase_report AS SELECT repo_root, change_id, phase, COALESCE(sum(cost_usd), 0.0) AS cost_usd, COALESCE(sum(input_tokens), 0) AS input_tokens, COALESCE(sum(output_tokens), 0) AS output_tokens, COALESCE(sum(duration_ms), 0) AS duration_ms, count_star() AS step_count, min(started_at) AS first_seen FROM step_events GROUP BY repo_root, change_id, phase ORDER BY repo_root, change_id, first_seen ASC, phase ASC;;
CREATE VIEW repo_report AS SELECT regexp_extract(repo_root, '[^/]+$') AS repo_basename, change_id, COALESCE(sum(cost_usd), 0.0) AS cost_usd, COALESCE(sum(input_tokens), 0) AS input_tokens, COALESCE(sum(output_tokens), 0) AS output_tokens, count_star() AS step_count, min(started_at) AS first_seen FROM step_events GROUP BY 1, change_id ORDER BY repo_basename, first_seen ASC, change_id ASC;;
CREATE INDEX idx_step_events_change ON step_events(repo_root, change_id);;
CREATE INDEX idx_tool_calls_change ON tool_calls(repo_root, change_id);;
COMMIT;
